package org.apache.commons.math.geometry.euclidean.threed;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Unit tests for the Rotation(Vector3D, Vector3D, Vector3D, Vector3D) constructor.
 * Aiming for high branch and line coverage.
 */
public class Rotation_Rotation_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testConstructorWithZeroNorm() {
        Vector3D u1 = Vector3D.ZERO;
        Vector3D u2 = new Vector3D(1, 0, 0);
        Vector3D v1 = new Vector3D(0, 1, 0);
        Vector3D v2 = new Vector3D(0, 0, 1);

        try {
            new Rotation(u1, u2, v1, v2);
            fail("Expected MathRuntimeException due to zero norm");
        } catch (MathRuntimeException e) {
            // Success: Exception thrown as expected
        }
    }

    @Test
    public void testConstructorIdentity() {
        // Case where vectors are perfectly aligned (Identity rotation)
        // This triggers the innermost 'if (c == 0)' block
        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        Vector3D v1 = new Vector3D(1, 0, 0);
        Vector3D v2 = new Vector3D(0, 1, 0);

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        assertEquals(1.0, rotation.getQ0(), EPSILON);
        assertEquals(0.0, rotation.getQ1(), EPSILON);
        assertEquals(0.0, rotation.getQ2(), EPSILON);
        assertEquals(0.0, rotation.getQ3(), EPSILON);
    }

    @Test
    public void testConstructorStandardRotation() {
        // A simple 90 degree rotation around Z axis
        // u1=(1,0,0), u2=(0,1,0) -> v1=(0,1,0), v2=(-1,0,0)
        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        Vector3D v1 = new Vector3D(0, 1, 0);
        Vector3D v2 = new Vector3D(-1, 0, 0);

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        // Expected: q0 = cos(45) = 0.707, q3 = sin(45) = 0.707 (around Z)
        // Note: The implementation logic for q1,q2,q3 depends on the cross product k
        // Let's verify using applyTo
        Vector3D testVec = new Vector3D(1, 0, 0);
        Vector3D result = rotation.applyTo(testVec);

        assertEquals(0.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
        assertEquals(0.0, result.getZ(), EPSILON);
    }

    @Test
    public void testConstructorComplexRotation() {
        // Test with non-orthogonal input vectors to exercise the alpha/beta coefficient logic
        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(1, 1, 0); // Not orthogonal to u1
        Vector3D v1 = new Vector3D(1, 0, 0);
        Vector3D v2 = new Vector3D(1, 1, 1); // Not orthogonal to v1

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        // Verify consistency: applying rotation to u1 should give v1 (scaled appropriately by the constructor logic)
        // The constructor ensures (v1'|v1') = (u1|u1)
        Vector3D u1Rotated = rotation.applyTo(u1);
        assertEquals(v1.getX(), u1Rotated.getX(), EPSILON);
        assertEquals(v1.getY(), u1Rotated.getY(), EPSILON);
        assertEquals(v1.getZ(), u1Rotated.getZ(), EPSILON);
    }

    @Test
    public void testConstructorNearSingularityPlane1() {
        // This test targets the 'if (c == 0)' block where we try the first alternative (v3)
        // We set up vectors such that the initial k is in the u1-u2 plane
        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);

        // v1, v2 chosen such that k is in XY plane, but v3 (cross product) helps resolve it
        Vector3D v1 = new Vector3D(1, 0, 0);
        Vector3D v2 = new Vector3D(0, 0, 1); 

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        // Verify rotation actually works
        Vector3D rotatedU2 = rotation.applyTo(u2);
        // u2 is (0,1,0). v2 is (0,0,1). Since v1 is same as u1, rotation maps u2 to v2.
        assertEquals(0.0, rotatedU2.getX(), EPSILON);
        assertEquals(0.0, rotatedU2.getY(), EPSILON);
        assertEquals(1.0, rotatedU2.getZ(), EPSILON);
    }

    @Test
    public void testConstructorNearSingularityPlane2() {
        // Targets the second fallback: "the (q1, q2, q3) vector is also close to the (u1, u3) plane"
        // This is a highly specific geometric configuration. 
        // We use a rotation that is almost identity but slightly offset to avoid the c==0 identity check
        // but trigger the fallback branches.

        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        // Rotate slightly around X axis
        Vector3D v1 = new Vector3D(1, 0, 0);
        Vector3D v2 = new Vector3D(0, Math.cos(0.01), Math.sin(0.01));

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        Vector3D rotatedU2 = rotation.applyTo(u2);
        assertEquals(0.0, rotatedU2.getX(), 1e-5);
        assertEquals(Math.cos(0.01), rotatedU2.getY(), 1e-5);
        assertEquals(Math.sin(0.01), rotatedU2.getZ(), 1e-5);
    }
}
